<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {Plus,BookOpen,Search,Grid2x2,List,Check,Pin,Heart,MoreHorizontal,X,SlidersHorizontal,ArrowUpRight,Upload} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import AssetView from '../media/AssetView.vue'
import OriginalCover from '../catalog/OriginalCover.vue'
import LibraryPortrait from '../presentation/LibraryPortrait.vue'
import {useAssetIndex} from '../media/asset-index'
import {composeMedia} from '../media/compose'
import ImportQueuePanel from '../catalog/ImportQueuePanel.vue'
import {primaryLibraryLinks,type MainReadingLine} from '../writing/main-line'
import type {LocalBranch} from '../writing/contract'
import {canonical,type Document,type LocalStory,type ProgressAnchor,type Paragraph} from '../domain/local-contract'
import BookDetailsPanel from '../catalog/BookDetailsPanel.vue'
import AddWorkPanel from '../catalog/AddWorkPanel.vue'
import type {OriginalStoryDraft} from '../catalog/original-story'
import type {PlayIntent} from '../playable/contract'
import type {CompanionCreationDraft} from '../companion/creation'
import {originalStories} from '../catalog/original-seeds'
import {importLocalText} from '../repositories/local-import'
import CollectionDetails from '../catalog/CollectionDetails.vue'
import {collectionIndex,collectionQuery,updateCollectionMetadata,addCollectionToGroup,collectionTypeId,collectionLabels,validateCollectionType,type CollectionTypeView,type CollectionFilter,type CollectionItem} from '../catalog/collection-index'
import type {ChatSession} from '../tavern/chat-contract'
import BookDeletePanel from '../catalog/BookDeletePanel.vue'
import {libraryQuery,defaultLibraryView,libraryViewId,validateLibraryView,updateBookMetadata,addBooksToGroup,currentReading,groupsOf,type LibraryView} from '../catalog/library-management'
import {mainLineKey} from '../writing/main-line'
const {rows:assets}=useAssetIndex()
const route=useRoute(),store=useLocal(),router=useRouter(),books=ref<Document<LocalStory>[]>([]),search=ref(''),importOpen=ref(route.query.imports==='1'),error=ref(''),loaded=ref(false)
const mainLines=ref(new Map<string,string>())
const mediaLifecycle=new AbortController();let disposed=false
const view=ref<LibraryView>({...defaultLibraryView}),viewRevision=ref(0),reading=ref(new Map<string,{at:string;position:number}>()),addedDates=ref(new Map<string,string>()),details=ref<Document<LocalStory>|null>(null),selecting=ref(false),selected=ref(new Set<string>()),groupName=ref(''),managing=ref(false),deleteIds=ref<string[]|null>(null)
const visible=computed(()=>libraryQuery(books.value,{...view.value,query:search.value},reading.value,addedDates.value))
const extras=ref<Document[]>([]),collectionType=ref<CollectionFilter>('all'),typeRevision=ref(0),typeBusy=ref(false),typeConflict=ref(false),typeRetry=ref<CollectionFilter|null>(null),collectionDetail=ref<CollectionItem|null>(null),recentExtras=ref(new Map<string,string>())
const allItems=computed(()=>collectionIndex([...books.value,...extras.value],reading.value,addedDates.value,recentExtras.value)),mixedVisible=computed(()=>collectionQuery(allItems.value,{...view.value,query:search.value},collectionType.value))
const resumeBook=computed(()=>{if(search.value||view.value.filter!=='all'||view.value.tag||view.value.group||selecting.value||!['all','story'].includes(collectionType.value))return null;return [...books.value].filter(book=>reading.value.get(book.id)?.at).sort((a,b)=>reading.value.get(b.id)!.at.localeCompare(reading.value.get(a.id)!.at))[0]||null})
const tagOptions=computed(()=>[...new Set(allItems.value.flatMap(row=>row.tags))].sort()),groupOptions=computed(()=>[...new Set(allItems.value.flatMap(row=>row.groups))].sort())
let typeIntent:{id:string;type:CollectionFilter;revision:number}|null=null
async function chooseType(type:CollectionFilter){const vault=store.vault;if(!vault||typeBusy.value||typeConflict.value||managing.value||bulkIntent.value)return;typeBusy.value=true;error.value='';if(!typeIntent||typeIntent.type!==type)typeIntent={id:crypto.randomUUID(),type,revision:typeRevision.value};const current=typeIntent;try{await vault.commit(current.id,'settings',collectionTypeId,current.revision,{assetType:'library-type',type:current.type});if(!disposed&&store.vault===vault){typeRevision.value=current.revision+1;collectionType.value=current.type;typeIntent=null;typeRetry.value=null;endSelection()}}catch(e){if(!disposed&&store.vault===vault){error.value=(e as Error).message;typeConflict.value=(e as {code?:string}).code==='REVISION_CONFLICT';typeRetry.value=typeConflict.value?null:current.type}}finally{if(!disposed)typeBusy.value=false}}
async function recheckType(){const vault=store.vault;if(!vault||typeBusy.value)return;typeBusy.value=true;try{const row=await vault.read<CollectionTypeView>(collectionTypeId);if(disposed||store.vault!==vault||!vault.unlocked)return;if(row)validateCollectionType(row.value,collectionTypeId);collectionType.value=row?.value.type||'all';typeRevision.value=row?.revision||0;typeIntent=null;typeConflict.value=false;typeRetry.value=null;error.value='';endSelection()}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed)typeBusy.value=false}}
function entryPath(item:CollectionItem){return item.kind==='world'?{path:'/local/play/'+item.id}:item.kind==='story'?{path:'/local/read/'+item.id,query:{branch:mainLines.value.get(item.id)}}:item.kind==='card'?{path:'/local/characters',query:{card:item.id}}:{path:'/local/companions/'+item.id}}
function originalBook(item:CollectionItem){return item.document as Document<LocalStory>}
function openItemDetails(item:CollectionItem){if(item.kind==='story')details.value=originalBook(item);else collectionDetail.value=item}
const addOpen=ref(false),originalDrafts=ref<Document<OriginalStoryDraft>[]>([]),companionDrafts=ref<Document<CompanionCreationDraft>[]>([]),playableDrafts=ref<Document<PlayIntent>[]>([]),sampleBusy=ref(false),sampleDismissed=ref(false)
let welcomeRevision=0,welcomeIntent:{id:string;revision:number}|null=null
async function hideSample(){const vault=store.vault;if(!vault||sampleBusy.value)return;sampleBusy.value=true;welcomeIntent??={id:crypto.randomUUID(),revision:welcomeRevision};try{await vault.commit(welcomeIntent.id,'settings','settings:library-welcome',welcomeIntent.revision,{assetType:'library-welcome',dismissed:true});if(!disposed&&store.vault===vault)sampleDismissed.value=true}catch(e){if(!disposed)error.value=(e as Error).message}finally{sampleBusy.value=false}}
async function openSample(){const vault=store.vault;if(!vault||sampleBusy.value)return;sampleBusy.value=true;try{const seed=originalStories[0]!,id=await importLocalText(vault,new File([seed.text],seed.title+'.txt',{type:'text/plain'}),'utf-8',()=>{},mediaLifecycle.signal);if(!disposed&&store.vault===vault&&vault.unlocked)await router.push('/local/read/'+id)}catch(e){if(!disposed)error.value=(e as Error).message}finally{sampleBusy.value=false}}
const bulkConflict=ref(false)
type BulkAction='pin'|'favorite'|'group'
const bulkIntent=ref<{operationId:string;documents:Document[];action:BulkAction;value:boolean;group:string}|null>(null)
const selectedStories=computed(()=>allItems.value.filter(item=>item.kind==='story'&&selected.value.has(item.id)).map(item=>item.id))
const paragraphLengths=new Map<string,number>()
let restoringScroll=true,viewLoaded=false,viewTimer:ReturnType<typeof setTimeout>|null=null,viewWork=Promise.resolve(),loadEpoch=0
function toggle(id:string){if(managing.value||bulkIntent.value)return;const next=new Set(selected.value);if(next.has(id))next.delete(id);else next.add(id);selected.value=next}
function allVisible(){if(!managing.value&&!bulkIntent.value)selected.value=new Set(mixedVisible.value.map(row=>row.id))}
function endSelection(){if(managing.value||bulkIntent.value)return;selecting.value=false;selected.value=new Set();bulkConflict.value=false}
async function recheckSelection(){if(managing.value)return;error.value='';await load();if(error.value)return;bulkIntent.value=null;bulkConflict.value=false;selected.value=new Set([...selected.value].filter(id=>allItems.value.some(item=>item.id===id)))}
async function saveView(){const vault=store.vault;if(!vault||!viewLoaded||disposed)return;if(viewTimer){clearTimeout(viewTimer);viewTimer=null}const value:LibraryView={...view.value,query:search.value};viewWork=viewWork.then(async()=>{if(disposed||store.vault!==vault)return;try{validateLibraryView(value);for(let attempt=0;attempt<3;attempt++){const latest=await vault.read<LibraryView>(libraryViewId);if(disposed||store.vault!==vault)return;if(latest&&canonical(latest.value)===canonical(value)){viewRevision.value=latest.revision;return}try{const receipts=await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:libraryViewId,expectedRevision:latest?.revision||0,value}]);if(!disposed&&store.vault===vault)viewRevision.value=receipts[0]!.revision;return}catch(error){if((error as {code?:string}).code!=='REVISION_CONFLICT'||attempt===2)throw error}}}catch(e){if(!disposed)error.value=(e as Error).message}});await viewWork}
watch(()=>canonical({...view.value,query:search.value}),()=>{if(!viewLoaded)return;if(viewTimer)clearTimeout(viewTimer);viewTimer=setTimeout(()=>void saveView(),350)})
async function changeSelected(action:BulkAction,value=true){
 const vault=store.vault;if(!vault||managing.value||!selected.value.size||bulkIntent.value)return
 const documents=allItems.value.filter(item=>selected.value.has(item.id)).map(item=>item.document)
 if(documents.length!==selected.value.size){error.value='所选作品已改变，请重新选择';return}
 bulkIntent.value={operationId:crypto.randomUUID(),documents:JSON.parse(canonical(documents)),action,value,group:action==='group'?groupName.value.trim():''}
 await runBulkIntent()
}
async function runBulkIntent(){
 const vault=store.vault,intent=bulkIntent.value;if(!vault||!intent||managing.value||bulkConflict.value)return;managing.value=true;error.value=''
 try{
  if(intent.action==='group')await addCollectionToGroup(vault,intent.operationId,intent.documents,intent.group)
  else await updateCollectionMetadata(vault,intent.operationId,intent.documents,intent.action==='pin'?{pinned:intent.value}:{favorite:intent.value})
  if(!disposed&&store.vault===vault&&vault.unlocked){bulkIntent.value=null;groupName.value='';bulkConflict.value=false;selecting.value=false;selected.value=new Set();await load()}
 }catch(e){if(!disposed&&store.vault===vault){error.value=(e as Error).message;const code=(e as {code?:string}).code;bulkConflict.value=code==='REVISION_CONFLICT'||code==='LIBRARY_SNAPSHOT';if(['BOOK_METADATA','LIBRARY_METADATA','LIBRARY_SELECTION'].includes(code||''))bulkIntent.value=null}}
 finally{if(!disposed&&store.vault===vault)managing.value=false}
}
async function quick(row:Document<LocalStory>,field:'favorite'|'pinned'){const vault=store.vault;if(!vault||managing.value)return;managing.value=true;try{await updateBookMetadata(vault,crypto.randomUUID(),[row],{[field]:!row.value[field]});if(!disposed&&store.vault===vault)await load()}catch(e){error.value=(e as Error).message}finally{managing.value=false}}
async function detailsSaved(){details.value=null;await load()}
async function booksDeleted(){endSelection();details.value=null;await load()}
function committed(event:Event){const detail=(event as CustomEvent<{vaultId:string;kinds:string[];ids:string[]}>).detail;if(detail?.vaultId===store.vault?.id&&(detail.kinds.some(k=>['story','branch','progress','card','companion','session','world','checkpoint'].includes(k))||detail.ids.some(id=>id.startsWith('settings:main-reading-line:')||id.startsWith('story-draft:')||id.startsWith('companion-draft:')||id.startsWith('play-intent:'))))void load()}
function scrolled(){if(viewLoaded&&!restoringScroll&&!disposed)view.value.scroll=Math.min(10_000_000,Math.max(0,window.scrollY))}
function pageHidden(){if(document.visibilityState==='hidden'){scrolled();void saveView()}}
function pageLeaving(){scrolled();void saveView()}
onBeforeRouteLeave(async()=>{if(managing.value||bulkIntent.value)return false;view.value.scroll=window.scrollY;await saveView()})
function cover(book:Document<LocalStory>){return assets.value.find(row=>!row.value.retired&&row.value.links.some(link=>link.targetId===book.id&&link.targetKind==='story'&&link.targetRevision===book.revision&&link.role==='cover'))}
async function coverBook(book:Document<LocalStory>){const vault=store.vault;if(!vault)return;try{const destination=await composeMedia(vault,{signal:mediaLifecycle.signal,source:{targetId:book.id,targetKind:'story',targetRevision:book.revision,role:'cover'}});if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){error.value=(e as Error).message}}
async function load(){const vault=store.vault;if(!vault)return;const ticket=++loadEpoch;try{
 const [stories,anchors,savedView,cards,companions,sessions,typeView,worlds]=await Promise.all([vault.list<LocalStory>('story'),vault.list<ProgressAnchor>('progress'),!viewLoaded?vault.read<LibraryView>(libraryViewId):Promise.resolve(null),vault.list('card'),vault.list('companion'),vault.list<ChatSession>('session'),!viewLoaded?vault.read<CollectionTypeView>(collectionTypeId):Promise.resolve(null),vault.list('world')])
 const [drafts,welcome,companionPending,playablePending]=await Promise.all([vault.listPrefix<OriginalStoryDraft>('story-draft:'),!viewLoaded?vault.read<{assetType:'library-welcome';dismissed:boolean}>('settings:library-welcome'):Promise.resolve(null),vault.listPrefix<CompanionCreationDraft>('companion-draft:'),vault.listPrefix<PlayIntent>('play-intent:')])
 const documents=[...stories,...cards,...companions,...worlds]
 const settings=await vault.readMany<MainReadingLine>(stories.map(r=>mainLineKey(r.id))),branches=await vault.readMany<LocalBranch>(settings.filter(r=>r.value.branchId).map(r=>r.value.branchId!))
 if(disposed||store.vault!==vault||ticket!==loadEpoch)return
 const dates=new Map<string,string>();for(let start=0;start<documents.length;start+=64){const values=await Promise.all(documents.slice(start,start+64).map(async row=>[row.id,(await vault.read(row.id,1))?.updatedAt||row.updatedAt] as [string,string]));if(disposed||store.vault!==vault||ticket!==loadEpoch)return;for(const entry of values)dates.set(...entry)}
 const links=primaryLibraryLinks(settings,branches),byBranch=new Map(branches.map(r=>[r.id,r])),byProgress=new Map(anchors.map(r=>[r.id,r])),required=new Set<string>();for(const row of stories){const line=links.get(row.id),ids=line?byBranch.get(line)!.value.paragraphIds:row.value.paragraphIds,anchor=byProgress.get('progress:'+row.id+(line?':'+line:''));if(anchor&&ids.includes(anchor.value.paragraphId))for(const id of ids)if(!paragraphLengths.has(id))required.add(id)}const missing=[...required];for(let start=0;start<missing.length;start+=128){const rows=await vault.readMany<Paragraph>(missing.slice(start,start+128));if(disposed||store.vault!==vault||ticket!==loadEpoch)return;for(const row of rows)if(row.kind==='paragraph')paragraphLengths.set(row.id,row.value.text.length)}
 playableDrafts.value=playablePending.filter(r=>r.value.type==='create'&&r.value.status==='ready');originalDrafts.value=drafts.filter(row=>['editing','ready'].includes(row.value.status));companionDrafts.value=companionPending.filter(row=>['editing','ready'].includes(row.value.status));if(welcome)sampleDismissed.value=welcome.value.dismissed;welcomeRevision=welcome?.revision||welcomeRevision;
 extras.value=[...cards,...companions,...worlds];const recent=new Map<string,string>();for(const session of sessions){if(!session.value.messageIds.length)continue;for(const card of session.value.cards)if((recent.get(card.id)||'')<session.updatedAt)recent.set(card.id,session.updatedAt);if(session.value.companionId&&(recent.get(session.value.companionId)||'')<session.updatedAt)recent.set(session.value.companionId,session.updatedAt)}for(const row of worlds){const intent=playablePending.filter(r=>r.value.worldId===row.id&&r.value.status==='completed').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];if(intent)recent.set(row.id,intent.updatedAt)}recentExtras.value=recent;
 books.value=stories;addedDates.value=dates;mainLines.value=links;reading.value=new Map(stories.map(row=>{const branchId=mainLines.value.get(row.id),paragraphIds=branchId?byBranch.get(branchId)!.value.paragraphIds:row.value.paragraphIds;return [row.id,currentReading(row,paragraphIds,byProgress.get('progress:'+row.id+(branchId?':'+branchId:'')),paragraphLengths)]}))
 if(!viewLoaded){if(typeView){validateCollectionType(typeView.value,collectionTypeId);collectionType.value=typeView.value.type;typeRevision.value=typeView.revision}if(savedView){validateLibraryView(savedView.value);view.value={...savedView.value};search.value=savedView.value.query;viewRevision.value=savedView.revision}const savedScroll=view.value.scroll;viewLoaded=true;await nextTick();requestAnimationFrame(()=>{if(!disposed){window.scrollTo(0,savedScroll);requestAnimationFrame(()=>{if(!disposed)restoringScroll=false})}})}
 if(!bulkIntent.value)selected.value=new Set([...selected.value].filter(id=>allItems.value.some(item=>item.id===id)))
 }catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed&&ticket===loadEpoch)loaded.value=true}}
onMounted(()=>{void load();window.addEventListener('reader-private-commit',committed);window.addEventListener('scroll',scrolled,{passive:true});window.addEventListener('pagehide',pageLeaving);document.addEventListener('visibilitychange',pageHidden)});onUnmounted(()=>{disposed=true;window.removeEventListener('scroll',scrolled);window.removeEventListener('pagehide',pageLeaving);document.removeEventListener('visibilitychange',pageHidden);window.removeEventListener('reader-private-commit',committed);if(viewTimer)clearTimeout(viewTimer);mediaLifecycle.abort()})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">YOUR STORIES</span><h1>书架</h1></div><div class="final-page-actions"><button v-if="allItems.length" :disabled="managing||!!bulkIntent" :aria-pressed="selecting" @click="selecting?endSelection():selecting=true">{{selecting?'取消':'选择'}}</button><button class="final-icon-button" aria-label="导入书籍" :aria-pressed="importOpen" @click="importOpen=!importOpen"><Upload :size="19"/></button><button class="final-primary" aria-label="添加作品" @click="addOpen=true"><Plus :size="18"/>添加</button></div></div>
<div v-if="playableDrafts.length" class="library-drafts" aria-label="待开始的文游"><RouterLink v-for="draft in playableDrafts" :key="draft.id" :to="{path:'/local/new-world',query:{intent:draft.id}}"><span>{{draft.value.definition?.name}}</span><small>开始游玩</small></RouterLink></div><AddWorkPanel v-if="addOpen" @close="addOpen=false" @import="addOpen=false;importOpen=true"/><div v-if="originalDrafts.length" class="library-drafts" aria-label="未完成的新故事"><RouterLink v-for="draft in originalDrafts" :key="draft.id" :to="{path:'/local/new-story',query:{draft:draft.id}}"><BookOpen :size="18"/><span>{{draft.value.title||'未命名的故事'}}</span><small>{{draft.value.status==='ready'?'继续保存':'草稿'}}</small></RouterLink></div>
<div v-if="companionDrafts.length" class="library-drafts" aria-label="未完成的新伴侣"><RouterLink v-for="draft in companionDrafts" :key="draft.id" :to="{path:'/local/companions',query:{draft:draft.id}}"><Heart :size="18"/><span>{{draft.value.name||'未命名的伴侣'}}</span><small>{{draft.value.status==='ready'?'继续保存':'草稿'}}</small></RouterLink></div>
<ImportQueuePanel v-if="importOpen" :key="store.vault?.id" @close="importOpen=false" @committed="load"/>
<p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="typeConflict" :disabled="typeBusy" @click="recheckType">载入当前书架类型</button><button v-else-if="typeRetry" :disabled="typeBusy" @click="chooseType(typeRetry)">重试保存类型</button><button v-if="bulkConflict" :disabled="managing" @click="recheckSelection">重新检查所选作品</button><button v-else-if="bulkIntent&&!managing" @click="runBulkIntent">重试批量保存</button><p v-if="managing&&bulkIntent" class="final-subtle" role="status">正在保存选中作品…</p><div v-if="allItems.length" class="library-tools"><nav class="collection-types" aria-label="作品类型"><button v-for="(label,type) in collectionLabels" :key="type" :aria-pressed="collectionType===type" :disabled="typeBusy||typeConflict||!!typeRetry||managing||!!bulkIntent" @click="chooseType(type)">{{label}}</button></nav><label class="final-search library-search"><Search :size="18"/><input v-model="search" type="search" aria-label="搜索名称与标签" maxlength="512" placeholder="寻找故事或人物"></label><details class="library-view-options"><summary><SlidersHorizontal :size="17"/>整理书架</summary><div class="library-toolbar"><label><span class="sr-only">书架范围</span><select v-model="view.filter" aria-label="书架范围"><option value="all">全部</option><option value="favorites">收藏</option><option value="pinned">置顶</option></select></label><label><span class="sr-only">标签筛选</span><select v-model="view.tag" aria-label="标签筛选"><option value="">全部标签</option><option v-for="tag in tagOptions" :key="tag" :value="tag">{{tag}}</option></select></label><label><span class="sr-only">分组筛选</span><select v-model="view.group" aria-label="分组筛选"><option value="">全部分组</option><option v-for="group in groupOptions" :key="group" :value="group">{{group}}</option></select></label><label><span class="sr-only">书架排序</span><select v-model="view.sort" aria-label="书架排序"><option value="recent">最近阅读</option><option value="added">最近添加</option><option value="title">名称</option><option value="progress">阅读进度</option></select></label><div class="library-layout"><button aria-label="网格视图" :aria-pressed="view.layout==='grid'" @click="view.layout='grid'"><Grid2x2 :size="18"/></button><button aria-label="列表视图" :aria-pressed="view.layout==='list'" @click="view.layout='list'"><List :size="18"/></button></div></div></details></div><article v-if="resumeBook" class="library-resume"><div class="resume-art"><AssetView v-if="cover(resumeBook)" :asset="cover(resumeBook)!"/><OriginalCover v-else :id="resumeBook.value.coverAssetId" :title="resumeBook.value.title"/></div><div class="resume-copy"><small>继续阅读</small><h2 :title="resumeBook.value.title">{{resumeBook.value.title}}</h2><p>{{resumeBook.value.chapters.length}} 章 · 已读 {{Math.round((reading.get(resumeBook.id)?.position||0)*100)}}%</p></div><RouterLink class="resume-open" :to="{path:'/local/read/'+resumeBook.id,query:{branch:mainLines.get(resumeBook.id)}}" :aria-label="'继续阅读 '+resumeBook.value.title"><ArrowUpRight :size="22"/></RouterLink></article><p v-if="!loaded" role="status">正在打开书架…</p><div v-else-if="!allItems.length" class="final-empty"><BookOpen :size="40"/><h2>第一本故事，等你打开</h2><button class="final-primary" @click="addOpen=true"><Plus :size="18"/>添加作品</button><div v-if="!sampleDismissed" class="library-sample"><button :disabled="sampleBusy" @click="openSample"><BookOpen :size="18"/>读一篇原创故事</button><button :disabled="sampleBusy" aria-label="收起示例推荐" @click="hideSample"><X :size="18"/></button></div><RouterLink class="final-text-link" to="/local/discover">发现更多故事</RouterLink></div><div v-else-if="!mixedVisible.length" class="final-empty"><Search :size="32"/><h2>没有找到作品</h2><button @click="search='';view.tag='';view.group='';view.filter='all';chooseType('all')">清除筛选</button></div><div v-else class="final-book-grid managed-library" :class="{'library-list':view.layout==='list'}"><article v-for="item in mixedVisible" :key="item.id" class="final-book" :class="{'is-selected':selected.has(item.id)}"><button v-if="selecting" :disabled="managing||!!bulkIntent" class="library-select-